from pathlib import Path
import json,base64
R=Path(__file__).resolve().parent
assets={f.name:'data:image/png;base64,'+base64.b64encode(f.read_bytes()).decode() for f in (R/'Layers').glob('*.png')}
assets['HeadTurnAtlas.png']='data:image/png;base64,'+base64.b64encode((R/'HeadTurnAtlas.png').read_bytes()).decode()
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>四头蛇 · 巨石转向正前试验</title><style>body{margin:0;background:#100b12;color:#dfc794;font:16px/1.7 Microsoft YaHei,sans-serif;padding:20px}main{max-width:1500px;margin:auto}section{display:grid;grid-template-columns:minmax(0,1fr) 285px;gap:20px}canvas{width:100%;border:1px solid #775832}aside{background:#221725;padding:18px}button,select{background:#3d2930;color:#e7cd97;border:1px solid #82633e;padding:7px 12px;margin:4px}input{accent-color:#c49a53}input[type=range]{width:100%}h1{font-size:21px;font-weight:500}p{color:#b7a18f}label{display:block;margin:16px 0}</style><main><h1>四头蛇 · 90° 换位试验</h1><section><div><canvas id="stage" width="1536" height="1024"></canvas><input id="seek" type="range" min="0" max="8" step=".01"><span id="clock"></span></div><aside><b id="front"></b><p>时间在前 → 身体转向 → 巨石在前。</p><button id="play">暂停</button><button id="replay">重新播放</button><button id="stone">巨石在前</button><button id="time">时间在前</button><label>手动转向 <span id="angleValue"></span><input id="angle" type="range" min="0" max="90" step=".1"></label><label><input id="bones" type="checkbox">显示骨骼</label><label>速度<select id="speed"><option value=".25">0.25×</option><option value=".5">0.5×</option><option selected value="1">1×</option></select></label><p>独立2D试验。头颈绕竖轴换位，按深度调整遮挡与透视；头部使用三档朝向补图。尚未接入游戏。</p></aside></section></main><script>window.RIG=__RIG__;window.ASSETS=__ASSETS__;</script><script>__JS__</script></html>'''
html=html.replace('__RIG__',(R/'Rig.json').read_text('utf8')).replace('__ASSETS__',json.dumps(assets)).replace('__JS__',(R/'turn.js').read_text('utf8'))
(R/'QuarterTurn.html').write_text(html,'utf8')
print('Quarter turn experiment built.')
